:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --tab-bg: #0f3460;
  --tab-active-bg: #e94560;
  --border: #2a2a4a;
  --focus: #ffb347;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-size: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: var(--font-size);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
  text-align: center;
  letter-spacing: 0.5px;
}

.tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.tab {
  flex: 1;
  min-width: 80px;
  padding: 12px 8px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  background: var(--tab-bg);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.tab:hover {
  background: var(--accent-hover);
}

.tab:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tab:active {
  transform: scale(0.97);
}

.tab.active {
  background: var(--tab-active-bg);
  border-color: var(--accent-hover);
}

.panel {
  display: none;
}

.panel.active {
  display: block;
}

textarea {
  width: 100%;
  min-height: 200px;
  padding: 12px;
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  resize: vertical;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
}

textarea::placeholder {
  color: #6b6b8a;
}

.char-count {
  margin-top: 8px;
  font-size: 0.875rem;
  color: #9a9ab0;
  text-align: right;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .tab {
    padding: 10px 4px;
    font-size: 0.9rem;
  }
  textarea {
    min-height: 160px;
  }
}

(function () {
  'use strict';

  var tabs = Array.prototype.slice.call(document.querySelectorAll('.tab'));
  var panels = Array.prototype.slice.call(document.querySelectorAll('.panel'));

  function getPanel(tabId) {
    return document.getElementById('panel-' + tabId.replace('tab-', ''));
  }

  function getTextarea(tabId) {
    return document.getElementById('notes-' + tabId.replace('tab-', ''));
  }

  function updateCount(panel) {
    var textarea = panel.querySelector('textarea');
    var countEl = panel.querySelector('.char-count');
    if (textarea && countEl) {
      var len = textarea.value.length;
      countEl.textContent = len + (len === 1 ? ' character' : ' characters');
    }
  }

  function activateTab(tab) {
    tabs.forEach(function (t) {
      var isActive = t === tab;
      t.classList.toggle('active', isActive);
      t.setAttribute('aria-selected', String(isActive));
      t.setAttribute('tabindex', isActive ? '0' : '-1');
      var panel = getPanel(t.id);
      if (panel) {
        panel.classList.toggle('active', isActive);
        panel.hidden = !isActive;
      }
    });
    tab.focus();
  }

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      activateTab(tab);
    });

    tab.addEventListener('keydown', function (e) {
      var index = tabs.indexOf(tab);
      var next;
      if (e.key === 'ArrowRight') {
        e.preventDefault();
        next = tabs[(index + 1) % tabs.length];
        activateTab(next);
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        next = tabs[(index - 1 + tabs.length) % tabs.length];
        activateTab(next);
      } else if (e.key === 'Home') {
        e.preventDefault();
        activateTab(tabs[0]);
      } else if (e.key === 'End') {
        e.preventDefault();
        activateTab(tabs[tabs.length - 1]);
      }
    });
  });

  panels.forEach(function (panel) {
    var textarea = panel.querySelector('textarea');
    if (textarea) {
      textarea.addEventListener('input', function () {
        updateCount(panel);
      });
      updateCount(panel);
    }
  });
})();
